args.command:
python3 - <<'PY'
import workcell,json
out={}
for b in ['B1','B2','B3','B4']:
 a=[workcell.call('robot','locate',b).data for _ in range(12)]
 x=sum(p['x'] for p in a)/len(a);y=sum(p['y'] for p in a)/len(a)
 out[b]={'x':x,'y':y}
 print(b,x,y, 'ranges',min(p['x'] for p in a),max(p['x'] for p in a),min(p['y'] for p in a),max(p['y'] for p in a))
json.dump(out,open('/home/robot/vision_estimates.json','w'))
PY

